<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { AxiosError } from 'axios'
import { fetchPublicProject, type PublicProjectDetail } from '@/api/portfolio'
import MarkdownRenderer from '@/components/MarkdownRenderer.vue'
import ArticleOutline from '@/components/ArticleOutline.vue'
import EditorialMotif from '@/components/visual/EditorialMotif.vue'
import ImageZoomOverlay from '@/components/ui/ImageZoomOverlay.vue'
import { applyPageMeta } from '@/lib/seo'
import type { OutlineItem } from '@/types'

const route=useRoute();const project=ref<PublicProjectDetail|null>(null);const outline=ref<OutlineItem[]>([]);const notFound=ref(false);const loadFailed=ref(false);const drawerOpen=ref(false);const zoomOpen=ref(false)
const statusLabels:Record<string,string>={DEVELOPING:'开发中',COMPLETED:'已完成',ONLINE:'已上线'}
async function load(){project.value=null;outline.value=[];notFound.value=false;loadFailed.value=false;drawerOpen.value=false;zoomOpen.value=false;try{project.value=await fetchPublicProject(route.params.slug as string);applyPageMeta({title:project.value.title,description:project.value.summary,type:'article',image:project.value.coverUrl,publishedAt:project.value.publishedAt,modifiedAt:project.value.updatedAt})}catch(error){if(error instanceof AxiosError&&error.response?.status===404){notFound.value=true;applyPageMeta({title:'页面未找到',robots:'noindex,nofollow'})}else{loadFailed.value=true;applyPageMeta({title:'加载失败',robots:'noindex,nofollow'})}}}
onMounted(load);watch(()=>route.params.slug,load)
</script>

<template>
  <section v-if="notFound||loadFailed" class="case-state"><strong>{{notFound?'项目不存在或尚未公开':'加载失败，请稍后重试'}}</strong><RouterLink to="/portfolio">返回作品</RouterLink></section>
  <article v-else-if="project" class="case-study" :class="{'case-study--no-toc':!outline.length}">
    <header class="case-hero"><div class="case-hero__visual"><button v-if="project.coverUrl" type="button" class="case-hero__zoom" :aria-label="`点击放大查看原图：${project.title}`" @click="zoomOpen=true"><img :src="project.coverUrl" :alt="project.title"/><span class="case-hero__zoom-hint" aria-hidden="true">点击放大 ⤢</span></button><EditorialMotif v-else kind="portfolio" :seed="project.title" :label="project.title"/></div><ImageZoomOverlay :open="zoomOpen" :src="project.coverUrl ?? ''" :alt="`${project.title} 原图`" @close="zoomOpen=false"/><div class="case-hero__content"><nav><RouterLink to="/portfolio">作品</RouterLink><span>/</span><span>案例详情</span></nav><p class="case-hero__eyebrow">{{statusLabels[project.projectStatus]??project.projectStatus}} · CASE STUDY</p><h1>{{project.title}}</h1><strong v-if="project.role">{{project.role}}</strong><p>{{project.summary}}</p><div class="case-hero__meta"><span v-if="project.startedAt">开始 {{project.startedAt}}</span><span v-if="project.completedAt">完成 {{project.completedAt}}</span><span>更新 {{new Date(project.updatedAt).toLocaleDateString('zh-CN')}}</span></div><div class="case-hero__links"><a v-if="project.demoUrl" :href="project.demoUrl" target="_blank" rel="noopener noreferrer" class="primary">在线演示 <i>↗</i></a><a v-if="project.repositoryUrl" :href="project.repositoryUrl" target="_blank" rel="noopener noreferrer">代码仓库 <i>↗</i></a></div></div></header>
    <dl class="case-snapshot" aria-label="工程概览"><div><dt>角色</dt><dd>{{project.role||'未填写'}}</dd></div><div><dt>状态</dt><dd>{{statusLabels[project.projectStatus]??project.projectStatus}}</dd></div><div><dt>周期</dt><dd>{{project.startedAt||'—'}}<template v-if="project.completedAt"> → {{project.completedAt}}</template></dd></div><div><dt>技术栈</dt><dd>{{project.techStack.length}} 项</dd></div></dl>
    <div class="case-stack"><span v-for="tech in project.techStack" :key="tech">{{tech}}</span></div>
    <button v-if="outline.length" class="case-study__drawer-button" @click="drawerOpen=true">本页目录 · {{outline.length}}</button>
    <div class="case-study__reading"><main class="case-study__body"><MarkdownRenderer :source="project.bodyMarkdown" @outline="outline=$event"/><nav class="case-nav"><RouterLink v-if="project.previous" :to="`/portfolio/${project.previous.slug}`"><small>上一个案例</small><strong>← {{project.previous.title}}</strong></RouterLink><span v-else/><RouterLink v-if="project.next" :to="`/portfolio/${project.next.slug}`" class="next"><small>下一个案例</small><strong>{{project.next.title}} →</strong></RouterLink></nav></main><aside v-if="outline.length" class="case-study__toc"><ArticleOutline :items="outline"/></aside></div>
    <div v-if="drawerOpen" class="case-drawer" @click.self="drawerOpen=false"><div><header><strong>本页目录</strong><button @click="drawerOpen=false">×</button></header><ArticleOutline :items="outline"/></div></div>
  </article>
  <section v-else class="case-state">正在加载案例…</section>
</template>

<style scoped>
