}.case-drawer{display:none}.case-state{display:grid;min-height:300px;place-content:center;gap:12px;color:var(--text-muted);text-align:center}.case-state a{color:var(--primary)}@media(prefers-reduced-motion:reduce){.case-nav a{transition:none}}@media(max-width:1000px){.case-hero{grid-template-columns:1fr}.case-hero__visual{min-height:300px}.case-study__reading{grid-template-columns:1fr}.case-study__toc{display:none}.case-study__drawer-button{display:inline-flex;margin-bottom:var(--space-5);padding:9px 14px;border:1px solid var(--border-strong);border-radius:999px;color:var(--primary);background:var(--bg-surface);cursor:pointer}.case-drawer{position:fixed;inset:0;z-index:80;display:grid;align-items:end;background:rgb(0 0 0/.45)}.case-drawer>div{max-height:75vh;overflow:auto;padding:var(--space-5);border-radius:20px 20px 0 0;background:var(--bg-surface)}.case-drawer header{display:flex;justify-content:space-between;margin-bottom:var(--space-4)}.case-drawer button{border:0;color:var(--text-primary);background:transparent;font-size:24px}}@media(max-width:600px){.case-hero{border-radius:20px}.case-hero__visual{min-height:220px}.case-hero__content{padding:var(--space-5)}.case-nav{grid-template-columns:1fr}}
